def loss_sum(logits, labels):
    """先求和再數有效 token，才能正確合併長短不同的 micro-batch。"""
    count = (labels != IGNORE).sum()
    if count.item() == 0:
        raise ValueError("所有 labels 都被忽略：没有可學習的答案")
    loss = F.cross_entropy(
        logits.reshape(-1, logits.shape[-1]), labels.reshape(-1), ignore_index=IGNORE, reduction="sum"
    )
    return loss, count

inspected_source.masked_loss:
def masked_loss(logits, labels):
    total, count = loss_sum(logits, labels)
    return total / count

inspected_source.attention_mask:
def attention_mask(query_positions, key_positions, valid=None, segments=None):
    """True 代表可以看：因果、PAD、文件邊界是三個獨立條件。"""
    allowed = key_positions[None, :] <= query_positions[:, None]
    allowed = allowed[None, None]
    if valid is not None:
        allowed = allowed & valid[:, None, None, :]
    if segments is not None:
        allowed = allowed & (segments[:, None, :, None] == segments[:, None, None, :])
    return allowed
